<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Support Contact Form</title>
  <style>
    :root {
      --color-bg: #0b1120;
      --color-panel: #111827;
      --color-panel-strong: #1f2937;
      --color-text: #f9fafb;
      --color-muted-text: #cbd5e1;
      --color-border: #334155;
      --color-focus: #7dd3fc;
      --color-danger: #fda4af;
      --color-success: #86efac;
      --color-button: #38bdf8;
      --color-button-text: #082f49;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, #172554 0%, #0b1120 45%, #020617 100%);
      color: var(--color-text);
      line-height: 1.5;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: -3rem;
      padding: 0.75rem 1rem;
      border-radius: 0.75rem;
      background: var(--color-text);
      color: #000;
      text-decoration: none;
      font-weight: 700;
      z-index: 10;
    }

    .skip-link:focus {
      top: 1rem;
      outline: 3px solid var(--color-focus);
      outline-offset: 2px;
    }

    main {
      display: grid;
      place-items: center;
      min-height: 100vh;
      padding: 2rem 1rem;
    }

    .page-shell {
      width: min(100%, 42rem);
      background: linear-gradient(180deg, rgba(31, 41, 55, 0.98), rgba(15, 23, 42, 0.98));
      border: 1px solid var(--color-border);
      border-radius: 1.5rem;
      padding: clamp(1.5rem, 4vw, 2.5rem);
      box-shadow: 0 24px 80px rgba(2, 6, 23, 0.55);
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      color: #93c5fd;
      font-size: 0.95rem;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      font-weight: 700;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 5vw, 3rem);
      line-height: 1.1;
    }

    .intro,
    .form-note {
      color: var(--color-muted-text);
    }

    .intro {
      margin: 1rem 0 0.5rem;
      font-size: 1.05rem;
    }

    .form-note {
      margin: 0 0 1.5rem;
      font-size: 0.95rem;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      display: grid;
      gap: 0.5rem;
    }

    label {
      font-weight: 700;
      color: var(--color-text);
    }

    .required-indicator {
      color: #fca5a5;
    }

    input {
      width: 100%;
      padding: 0.9rem 1rem;
