    input[aria-invalid="true"] {
      border-color: var(--color-danger);
    }

    .helper-text,
    .error-text,
    .status-message {
      margin: 0;
      font-size: 0.95rem;
    }

    .helper-text {
      color: var(--color-muted-text);
    }

    .error-text {
      color: var(--color-danger);
    }

    .status-message {
      min-height: 1.5rem;
      color: var(--color-muted-text);
