       font-size: 0.95rem;
     }

     .helper-text {
       color: var(--color-muted-text);
     }

     .error-text {
       color: var(--color-danger);
     }

     .status-message {
       min-height: 1.5rem;
       color: var(--color-muted-text);
       font-weight: 600;
     }

     .status-message[data-state="error"] {
       color: var(--color-danger);
     }

     .status-message[data-state="success"] {
       color: var(--color-success);
     }

     button {
       justify-self: start;
       border: 0;
       border-radius: 999px;
       padding: 0.95rem 1.4rem;
       background: linear-gradient(180deg, #7dd3fc, var(--color-button));
       color: var(--color-button-text);
       font: inherit;
       font-weight: 800;
       cursor: pointer;
     }

     button:hover {
       filter: brightness(1.05);
     }

     @media (max-width: 40rem) {
       .page-shell {
         border-radius: 1.1rem;
       }

       button {
         width: 100%;
         justify-self: stretch;
       }
     }

     @media (forced-colors: active) {
       body,
       .page-shell,
       input,
       button {
         background: Canvas;
         color: CanvasText;
       }

       .page-shell,
       input,
       button {
         border: 1px solid ButtonBorder;
         box-shadow: none;
       }

       .skip-link {
         background: ButtonFace;
         color: ButtonText;
       }

       .error-text {
         color: CanvasText;
       }

       input:focus,
       button:focus,
       .skip-link:focus {
         outline: 2px solid Highlight;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>
   <main id="main-content"></main>

   <script>
     const fields = {
       fullName: {
         label: "Full name",
         type: "text",
         autocomplete: "name",
         required: true,
         placeholder: "Jordan Lee"
       },
       email: {
         label: "Email address",
         type: "email",
         autocomplete: "email",
         required: true,
         placeholder: "jordan@example.com"
       },
       phone: {
         label: "Phone number",
         type: "tel",
         autocomplete: "tel",
         required: false,
         placeholder: "555-123-4567",
         helperText: "Expected format: use digits with optional spaces, dashes, parentheses, or a leading +, for example 555-123-4567."
       }
     };

     function FormField(name, config) {
       const helperId = config.helperText ? name + "-help" : "";
       const errorId = name + "-error";
       const describedBy = [helperId, errorId].filter(Boolean).join(" ");
       const requiredText = config.required
         ? ' <span class="required-indicator" aria-hidden="true">*</span>'
         : ' <span class="helper-text">(optional)</span>';

       return `
         <div class="form-field">
           <label for="${name}">${config.label}${requiredText}</label>
           <input
             id="${name}"
             name="${name}"
             type="${config.type}"
             ${config.required ? "required" : ""}
             autocomplete="${config.autocomplete}"
             placeholder="${config.placeholder}"
             aria-describedby="${describedBy}"
             aria-errormessage="${errorId}"
             aria-invalid="false"
           >
           ${config.helperText ? `<p class="helper-text" id="${helperId}">${config.helperText}</p>` : ""}
           <p class="error-text" id="${errorId}" hidden></p>
         </div>
       `;
     }

     function SupportContactForm() {
       return `
         <form id="support-form" novalidate>
           ${Object.entries(fields).map(([name, config]) => FormField(name, config)).join("")}
           <p class="status-message" id="form-status" aria-live="polite"></p>
           <button type="submit">Send support request</button>
         </form>
       `;
     }

     function App() {
       return `
         <section class="page-shell" aria-labelledby="support-heading">
           <p class="eyebrow">Support</p>
           <h1 id="support-heading">Contact our support team</h1>
           <p class="intro">Share your details below and we will use them to follow up on your request.</p>
           <p class="form-note">Required fields are marked with <span class="required-indicator" aria-hidden="true">*</span>.</p>
           ${SupportContactForm()}
         </section>
       `;
     }

     document.querySelector("#main-content").innerHTML = App();

     const form = document.querySelector("#support-form");
     const statusMessage = document.querySelector("#form-status");

     function getErrorMessage(name, value) {
       const trimmedValue = value.trim();

       if (name === "fullName") {
         if (!trimmedValue) {
           return "Error: Enter your full name.";
         }
         return "";
       }

       if (name === "email") {
         if (!trimmedValue) {
           return "Error: Enter your email address.";
         }
         const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
         if (!emailPattern.test(trimmedValue)) {
           return "Error: Enter a valid email address, such as name@example.com.";
         }
         return "";
       }

       if (name === "phone") {
         if (!trimmedValue) {
           return "";
         }
         const digitsOnly = trimmedValue.replace(/\D/g, "");
         const phonePattern = /^\+?[\d()\-\s]+$/;
         if (!phonePattern.test(trimmedValue) || digitsOnly.length < 7 || digitsOnly.length > 15) {
           return "Error: Enter a valid phone number, such as 555-123-4567.";
         }
       }

       return "";
     }

     function setFieldState(input, message) {
       const errorElement = document.querySelector("#" + input.name + "-error");
       const isInvalid = Boolean(message);

       input.setAttribute("aria-invalid", String(isInvalid));
       errorElement.hidden = !isInvalid;
       errorElement.textContent = message;
     }

     function validateField(input) {
       const message = getErrorMessage(input.name, input.value);
       setFieldState(input, message);
       return !message;
     }

     form.addEventListener("input", (event) => {
       if (!(event.target instanceof HTMLInputElement)) {
         return;
       }

       validateField(event.target);
       if (statusMessage.textContent) {
         statusMessage.textContent = "";
         statusMessage.removeAttribute("data-state");
       }
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const inputs = Array.from(form.querySelectorAll("input"));
       const invalidInput = inputs.find((input) => !validateField(input));

       if (invalidInput) {
         statusMessage.textContent = "Please correct the highlighted fields and try again.";
         statusMessage.setAttribute("data-state", "error");
         invalidInput.focus();
         return;
       }

       statusMessage.textContent = "Your support request is ready to send.";
       statusMessage.setAttribute("data-state", "success");
     });
   </script>
 </body>
 </html>

')
